1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.security.NoSuchAlgorithmException;
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
29	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
34	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
35	    @Mapping(target = "locality", expression = "java(locality(owner))")
36	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
37	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
38	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    /**
42	     * Derives an owner's age band from its birth date, computed as the owner's age on its
43	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
44	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
45	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
46	     * response.
47	     *
48	     * @param owner the owner to derive the age band for
49	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
50	     *     is held
51	     */
52	    default String ageBand(Owner owner) {
53	        java.time.LocalDate birthDate = owner.getBirthDate();
54	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
55	        if (birthDate == null || registrationDate == null) {
56	            return null;
57	        }
58	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
59	        if (age < 18) {
60	            return "MINOR";
61	        }
62	        return age < 65 ? "ADULT" : "SENIOR";
63	    }
64	
65	    /**
66	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
67	     * email, otherwise {@code "PHONE"}.
68	     *
69	     * @param owner the owner to derive the contact preference for
70	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
71	     */
72	    default String contactPreference(Owner owner) {
73	        String email = owner.getEmail();
74	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
75	    }
76	
77	    /**
78	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
79	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
80	     * normalizing telephones into E.164 form.
81	     */
82	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
83	
84	    /**
85	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
86	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
87	     * The country code is taken as the longest recognized prefix (see
88	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
89	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
90	     * is returned unchanged.
91	     *
92	     * @param owner the owner to format the telephone display for
93	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
94	     *     digit string
95	     */
96	    default String telephoneDisplay(Owner owner) {
97	        String telephone = owner.getTelephone();
98	        if (telephone == null || !telephone.startsWith("+")) {
99	            return telephone;
100	        }
101	        String digits = telephone.substring(1);
102	        if (!digits.matches("[0-9]+")) {
103	            return telephone;
104	        }
105	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
106	            .filter(digits::startsWith)
107	            .max(java.util.Comparator.comparingInt(String::length))
108	            .orElseGet(() -> digits.substring(0, 1));
109	        String national = digits.substring(countryCode.length());
110	        StringBuilder sb = new StringBuilder("+").append(countryCode);
111	        for (int i = 0; i < national.length(); i += 3) {
112	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
113	        }
114	        return sb.toString();
115	    }
116	
117	    /**
118	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
119	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
120	     * the customer code's region is itself derived from the postcode (falling back to the city), the
121	     * locality now moves with the identity rather than being computed independently. The result is
122	     * {@code "UNKNOWN"} when no customer code is present.
123	     *
124	     * @param owner the owner to derive the locality for
125	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
126	     */
127	    default String locality(Owner owner) {
128	        String code = owner.getCustomerCode();
129	        if (code == null || code.isEmpty()) {
130	            return "UNKNOWN";
131	        }
132	        int dash = code.indexOf('-');
133	        return dash < 0 ? code : code.substring(0, dash);
134	    }
135	
136	    /**
137	     * Derives an owner's numeric membership level. Starts at {@code 1}, plus {@code 1} when an email
138	     * is present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}; these
139	     * pre-tenure factors are capped at {@code 3}. Level {@code 4} additionally requires a tenure of
140	     * more than {@code 365} days - the number of days between the owner's registration date and the
141	     * current server date. Because a newly created owner registers on the current date, its tenure is
142	     * zero, so a new owner never exceeds level {@code 3} even with an email and a namesake count of
143	     * {@code 0}.
144	     *
145	     * @param owner the owner to derive the membership level for
146	     * @return the membership level, between {@code 1} and {@code 4}
147	     */
148	    default Integer membershipLevel(Owner owner) {
149	        int level = 1;
150	        String email = owner.getEmail();
151	        if (email != null && !email.isBlank()) {
152	            level++;
153	        }
154	        Integer namesakeCount = owner.getNamesakeCount();
155	        if (namesakeCount != null && namesakeCount == 0) {
156	            level++;
157	        }
158	        level = Math.min(level, 3);
159	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
160	        long tenureDays = registrationDate == null ? 0
161	            : java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
162	        if (level == 3 && tenureDays > 365) {
163	            level = 4;
164	        }
165	        return level;
166	    }
167	
168	    /**
169	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
170	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
171	     * two digits (zero-padded) of the owner's registration date year (e.g. {@code NSW-1A2B3C4D-M26}).
172	     *
173	     * @param owner the owner to derive the membership number for
174	     * @return the formatted membership number
175	     */
176	    default String membershipNumber(Owner owner) {
177	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
178	        return owner.getCustomerCode() + "-M" + yy;
179	    }
180	
181	    /**
182	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
183	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
184	     * are ignored.
185	     *
186	     * @param owner the owner to derive the check digit for
187	     * @return the Luhn check digit, between {@code 0} and {@code 9}
188	     */
189	    default Integer checkDigit(Owner owner) {
190	        String code = owner.getCustomerCode();
191	        int sum = 0;
192	        boolean dbl = true;
193	        for (int i = code.length() - 1; i >= 0; i--) {
194	            char c = code.charAt(i);
195	            if (c < '0' || c > '9') {
196	                continue;
197	            }
198	            int d = c - '0';
199	            if (dbl) {
200	                d *= 2;
201	                if (d > 9) {
202	                    d -= 9;
203	                }
204	            }
205	            sum += d;
206	            dbl = !dbl;
207	        }
208	        return (10 - (sum % 10)) % 10;
209	    }
